/// The current time as stored in our timestamp columns: UTC, ISO 8601, with
/// milliseconds (`2026-11-16T20:15:13.123Z`).
pub fn now() -> String {
    sea_orm::prelude::ChronoUtc::now()
        .format("%Y-%m-%dT%H:%M:%S%.3fZ")
        .to_string()
}

/// Opens `unseen.db` in `data_dir` (WAL mode, foreign keys on), creates it if
/// it is missing, and applies every pending migration.
pub async fn connect(data_dir: &Path) -> Result<DatabaseConnection, DbErr> {
    let db = open(data_dir).await?;
    migration::Migrator::up(&db, None).await?;
    profiles::seed_defaults(&db).await?;
    Ok(db)
}

async fn open(data_dir: &Path) -> Result<DatabaseConnection, DbErr> {
    let options = SqliteConnectOptions::new()
        .filename(data_dir.join("unseen.db"))
        .create_if_missing(true)
        .journal_mode(SqliteJournalMode::Wal)
        .foreign_keys(true);
    let pool = SqlitePoolOptions::new()
        .connect_with(options)
        .await
        .map_err(|error| DbErr::Conn(RuntimeErr::SqlxError(error.into())))?;
    Ok(SqlxSqliteConnector::from_sqlx_sqlite_pool(pool))
}

#[cfg(test)]
mod tests {
    use sea_orm::{ConnectionTrait, Statement};

    use super::*;

    async fn tables(db: &DatabaseConnection) -> Vec<String> {
        let rows = db
            .query_all_raw(Statement::from_string(
                db.get_database_backend(),
                "SELECT name FROM sqlite_master WHERE type = 'table' ORDER BY name",
            ))
            .await
            .unwrap();
        rows.iter()
            .map(|row| row.try_get("", "name").unwrap())
            .collect()
    }

    #[tokio::test]
    async fn migrates_a_temp_database_from_zero() {
        let (db, dir) = testing::temp_db().await;
        let tables = tables(&db).await;
        for expected in [
            "account",
            "api_key_permissions",
            "audit_log",
            "blocklist",
            "collections",
            "custom_formats",
            "download_client_tags",
            "download_clients",
            "downloads",
            "api_keys",
            "indexer_tags",
            "indexers",
            "language_profiles",
            "movie_files",
            "movie_profiles",
            "movie_tags",
            "movies",
            "passkey",
            "quality_profiles",
            "quality_profile_custom_formats",
            "role_permissions",
            "roles",
            "root_folders",
            "session",
            "subtitles",
            "tags",
            "settings",
            "twoFactor",
            "user",
            "user_permissions",
            "user_roles",
            "verification",
        ] {
            assert!(tables.iter().any(|t| t == expected), "missing {expected}");
        }

        // A second start finds nothing to migrate and does not fail.
        db.close().await.unwrap();
        let db = connect(dir.path()).await.unwrap();
        assert_eq!(self::tables(&db).await, tables);
    }

    #[tokio::test]
    async fn migrates_on_top_of_m0_and_keeps_its_users() {
        // A database as M0 left it: only the first migration, with one user.
        let dir = tempfile::tempdir().unwrap();
        let db = open(dir.path()).await.unwrap();
        migration::Migrator::up(&db, Some(1)).await.unwrap();
        testing::insert_user(&db, "old").await;
        db.close().await.unwrap();

        let db = connect(dir.path()).await.unwrap();
        let row = db
            .query_one_raw(Statement::from_string(
                db.get_database_backend(),
                r#"SELECT disabled FROM "user" WHERE id = 'old'"#,
            ))
            .await
            .unwrap()
            .expect("the user is still there");
        assert!(!row.try_get::<bool>("", "disabled").unwrap());

        // A user inserted after the migration, without the column, is enabled too.
        testing::insert_user(&db, "new").await;
        let enabled = db
            .query_one_raw(Statement::from_string(
                db.get_database_backend(),
                r#"SELECT count(*) AS n FROM "user" WHERE disabled = 0"#,
            ))
            .await
            .unwrap()
            .unwrap();
        assert_eq!(enabled.try_get::<i64>("", "n").unwrap(), 2);
    }

    #[tokio::test]
    async fn migrates_on_top_of_m1_and_keeps_its_roles() {
        // A database as M1 left it: the first three migrations.
        let dir = tempfile::tempdir().unwrap();
        let db = open(dir.path()).await.unwrap();
        migration::Migrator::up(&db, Some(3)).await.unwrap();
        testing::insert_user(&db, "u1").await;
        db.close().await.unwrap();

        let db = connect(dir.path()).await.unwrap();
        let tables = tables(&db).await;
        assert!(tables.iter().any(|t| t == "movies"));
        let owner = db
            .query_one_raw(Statement::from_string(
                db.get_database_backend(),
                "SELECT count(*) AS n FROM roles WHERE is_owner = 1",
            ))
            .await
            .unwrap()
            .unwrap();
        assert_eq!(owner.try_get::<i64>("", "n").unwrap(), 1);
    }

    #[tokio::test]
    async fn custom_formats_enforce_uniqueness_and_cascades() {
        let (db, _dir) = testing::temp_db().await;
        let backend = db.get_database_backend();
        let exec = |sql: &str| db.execute_raw(Statement::from_string(backend, sql.to_owned()));
        let one = |sql: &str| db.query_one_raw(Statement::from_string(backend, sql.to_owned()));

        exec(
            "INSERT INTO custom_formats (name, specifications, created_at, updated_at) \
             VALUES ('CF1', '[]', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')",
        )
        .await
        .unwrap();
        let row = one(
            "SELECT include_when_renaming AS i, trash_synced AS s, specifications AS specs \
             FROM custom_formats WHERE name = 'CF1'",
        )
        .await
        .unwrap()
        .unwrap();
        assert!(!row.try_get::<bool>("", "i").unwrap());
        assert!(!row.try_get::<bool>("", "s").unwrap());
        assert_eq!(
            row.try_get::<serde_json::Value>("", "specs").unwrap(),
            serde_json::json!([])
        );

        assert!(
            exec(
                "INSERT INTO custom_formats (name, specifications, created_at, updated_at) \
                 VALUES ('CF1', '[]', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')",
            )
            .await
            .is_err()
        );

        for name in ["CF2", "CF3"] {
            exec(&format!(
                "INSERT INTO custom_formats (name, specifications, created_at, updated_at) \
                 VALUES ('{name}', '[]', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')",
            ))
            .await
            .unwrap();
        }
        assert!(
            exec("UPDATE custom_formats SET trash_id = 't1' WHERE name = 'CF2'")
                .await
                .is_ok()
        );
        assert!(
            exec("UPDATE custom_formats SET trash_id = 't1' WHERE name = 'CF3'")
                .await
                .is_err()
        );

        let profile = crate::profiles::create(
            &db,
            crate::profiles::Values {
                name: "CF profile".into(),
                upgrade_allowed: false,
                cutoff_quality_id: 7,
                items: serde_json::json!([
                    { "type": "quality", "qualityId": 7, "allowed": true }
                ]),
                language: "any".into(),
                min_format_score: 0,
                cutoff_format_score: 0,
                min_upgrade_format_score: 1,
            },
        )
        .await
        .unwrap();
        let cf1: i64 = one("SELECT id FROM custom_formats WHERE name = 'CF1'")
            .await
            .unwrap()
            .unwrap()
            .try_get("", "id")
            .unwrap();
        exec(&format!(
            "INSERT INTO quality_profile_custom_formats \
             (quality_profile_id, custom_format_id, score) VALUES ({}, {cf1}, 10)",
            profile.id
        ))
        .await
        .unwrap();

        exec(&format!("DELETE FROM custom_formats WHERE id = {cf1}"))
            .await
            .unwrap();
        let left = one("SELECT count(*) AS n FROM quality_profile_custom_formats")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(left.try_get::<i64>("", "n").unwrap(), 0);

        let cf2: i64 = one("SELECT id FROM custom_formats WHERE name = 'CF2'")
            .await
            .unwrap()
            .unwrap()
            .try_get("", "id")
            .unwrap();
        exec(&format!(
            "INSERT INTO quality_profile_custom_formats \
             (quality_profile_id, custom_format_id, score) VALUES ({}, {cf2}, 5)",
            profile.id
        ))
        .await
        .unwrap();
        exec(&format!(
            "DELETE FROM quality_profiles WHERE id = {}",
            profile.id
        ))
        .await
        .unwrap();
        let left = one("SELECT count(*) AS n FROM quality_profile_custom_formats")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(left.try_get::<i64>("", "n").unwrap(), 0);
    }
}
